        body: `つるかめ算は、鶴(足2本)と亀(足4本)が合わせて何匹かいて、頭の数(合計の数)と足の数(合計の量)が分かっているときに、鶴と亀がそれぞれ何匹(何羽)ずついるかを求める問題です。名前は鶴と亀ですが、実際には代金・得点・速さなど、あらゆる「2種類が混ざった」問題に使える最重要テクニックです。

■ 基本の考え方―「全部鶴だったら」と仮定する
鶴と亀が合わせて10匹いて、足の合計が32本だったとします。

①まず「全部鶴(足2本)だった」と仮定します。
　10匹全部が鶴なら、足の合計は 10×2＝20本 のはずです。

②実際の32本との差を求めます。
　32－20＝12本 足りません。

③この「12本の差」はどこから生まれるかというと、本当は亀だったのに鶴だと仮定してしまった分です。亀1匹は鶴より足が2本多い(4－2＝2)ので、亀が1匹増えるごとに差は2本ずつ増えていきます。

④差12本を、1匹あたりの差2本で割ると、
　12÷2＝6匹 が実際には亀だった数です。

⑤鶴の数は、全体10匹から亀6匹を引いて、
　10－6＝4羽

■ 答えの確認
鶴4羽×2本＋亀6匹×4本＝8＋24＝32本 ✓ 頭の数も4＋6＝10匹 ✓ 正しく求まりました。

★ ポイント：「全部○○だったら」の○○にあたる動物(仮定した方)の答えは、最初に求まる数(12÷2＝6)そのものではなく、「全体−その数」で求まります。仮定した数と、計算で出てくる数を取り違えないように注意しましょう。`,
